(()=>{'use strict';
const root=document.documentElement,media=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(hover: hover) and (pointer: fine)');
let disabled=media.matches;try{disabled=disabled||localStorage.getItem('portfolio-motion')==='off'}catch{}
const toggle=document.createElement('button');toggle.className='motion-toggle';toggle.type='button';document.querySelector('footer').insertBefore(toggle,document.querySelector('footer a'));
function sync(){root.classList.toggle('motion-off',disabled);toggle.textContent=disabled?'Motion: off':'Motion: on';toggle.setAttribute('aria-pressed',String(!disabled));}sync();toggle.addEventListener('click',()=>{disabled=!disabled;sync();try{localStorage.setItem('portfolio-motion',disabled?'off':'on')}catch{}});media.addEventListener('change',event=>{disabled=event.matches;sync()});
const progress=document.createElement('div');progress.className='scroll-progress';progress.setAttribute('aria-hidden','true');document.body.prepend(progress);
let scrollFrame=0;function updateProgress(){scrollFrame=0;if(scrollY<250)document.querySelectorAll('.links a').forEach(a=>{a.classList.remove('active');a.removeAttribute('aria-current')});const distance=root.scrollHeight-innerHeight;progress.style.transform=`scaleX(${distance>0?Math.min(1,Math.max(0,scrollY/distance)):0})`;}addEventListener('scroll',()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(updateProgress)},{passive:true});addEventListener('resize',updateProgress);updateProgress();
if('IntersectionObserver' in window){const reveal=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.remove('waiting');reveal.unobserve(entry.target)}})},{threshold:.08});document.querySelectorAll('.section-head,.project,.about>div,.job,.contact,.skill-row').forEach(el=>{el.classList.add('reveal','waiting');reveal.observe(el)});const navObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){document.querySelectorAll('.links a').forEach(a=>{const active=a.hash==='#'+entry.target.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}})},{rootMargin:'-15% 0px -50% 0px',threshold:0});document.querySelectorAll('#work,#about,#case-studies,#experience').forEach(el=>navObserver.observe(el));}
if(fine.matches){const glow=document.createElement('div');glow.className='cursor-glow';glow.setAttribute('aria-hidden','true');document.body.prepend(glow);let pointerFrame=0,x=0,y=0;document.addEventListener('pointermove',e=>{x=e.clientX;y=e.clientY;if(!disabled&&!pointerFrame)pointerFrame=requestAnimationFrame(()=>{glow.style.transform=`translate3d(${x}px,${y}px,0)`;glow.style.opacity='1';pointerFrame=0})},{passive:true});document.addEventListener('pointerleave',()=>glow.style.opacity='0');
function tilt(el,strength){let frame=0;el.addEventListener('pointermove',event=>{if(disabled)return;const r=el.getBoundingClientRect(),dx=(event.clientX-r.left)/r.width-.5,dy=(event.clientY-r.top)/r.height-.5;el.style.setProperty('--px',`${event.clientX-r.left}px`);el.style.setProperty('--py',`${event.clientY-r.top}px`);cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{el.style.transform=`perspective(1100px) rotateX(${-dy*strength}deg) rotateY(${dx*strength}deg)`})},{passive:true});el.addEventListener('pointerleave',()=>{cancelAnimationFrame(frame);el.style.transform=''})}document.querySelectorAll('.project').forEach(el=>tilt(el,5));tilt(document.querySelector('.orbit'),15);
}
})();
